import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from "remotion";
import { BRAND } from "@/lib/brand";
import { springIn, ambientDrift } from "../motion";

export const fps = 25;

const COLORS = {
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeTint: BRAND.colors.orangeTint,
};

const ORANGE_SOLID_TINT = "rgb(58, 28, 12)";

const Icon: React.FC<{ name: string; color: string }> = ({ name, color }) => {
  const common = {
    width: 64,
    height: 64,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: color,
    strokeWidth: 2,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
  };
  switch (name) {
    case "script":
      return (
        <svg {...common}>
          <rect x="5" y="3" width="14" height="18" rx="2.5" />
          <line x1="8.5" y1="8" x2="15.5" y2="8" />
          <line x1="8.5" y1="12" x2="15.5" y2="12" />
          <line x1="8.5" y1="16" x2="13" y2="16" />
        </svg>
      );
    case "hook":
      return (
        <svg {...common}>
          <path d="M12 3 L12 14 C12 17.5 9.5 20 6 20 C4 20 2 18 2 16" />
          <circle cx="12" cy="3.5" r="1.4" fill={color} stroke="none" />
        </svg>
      );
    case "cta":
      return (
        <svg {...common}>
          <path
            d="M6 4 L6 17 L9.5 13.8 L12 19 L14 18 L11.6 12.9 L16.5 12.9 Z"
            fill={color}
            stroke={color}
            strokeWidth="1.4"
          />
        </svg>
      );
    case "structure":
      return (
        <svg {...common}>
          <rect x="3.5" y="4.5" width="17" height="15" rx="2" />
          <line x1="3.5" y1="9.5" x2="20.5" y2="9.5" />
          <line x1="10" y1="9.5" x2="10" y2="19.5" />
        </svg>
      );
    case "titles":
      return (
        <svg {...common}>
          <line x1="5" y1="7" x2="19" y2="7" strokeWidth="3" />
          <line x1="5" y1="12.5" x2="15" y2="12.5" />
          <line x1="5" y1="17" x2="17.5" y2="17" />
        </svg>
      );
    case "metrics":
      return (
        <svg {...common}>
          <line x1="5" y1="20" x2="5" y2="13" strokeWidth="2.6" />
          <line x1="10" y1="20" x2="10" y2="8" strokeWidth="2.6" />
          <line x1="15" y1="20" x2="15" y2="15" strokeWidth="2.6" />
          <line x1="20" y1="20" x2="20" y2="5" strokeWidth="2.6" />
        </svg>
      );
    default:
      return null;
  }
};

const ITEMS = [
  { label: "Hooks", icon: "hook", start: 62 },
  { label: "CTAs", icon: "cta", start: 85 },
  { label: "Content structure", icon: "structure", start: 114 },
  { label: "Titles", icon: "titles", start: 141 },
  { label: "Metrics", icon: "metrics", start: 163 },
];

export const durationInFrames = 313;

// Fixed layout constants — content anchors to the top so new items grow
// downward without shifting the header.
const HEADER_HEIGHT = 132;
const HEADER_GAP = 36;
const ITEM_HEIGHT = 156; // 96 icon + 30*2 padding == approx visible height
const ITEM_GAP = 28;

const MainComposition: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const headerIn = springIn(frame, vfps, 2, "LIQUID");
  const headerDrift = ambientDrift(frame, 4, 120, "header");
  const eyebrowIn = springIn(frame, vfps, 18, "GENTLE");

  let activeIdx = -1;
  ITEMS.forEach((it, i) => {
    if (frame >= it.start) activeIdx = i;
  });

  // Total stack height with all items visible — used to vertically center
  // the whole block in the canvas so it sits comfortably regardless of
  // how many items have appeared.
  const fullStackHeight =
    HEADER_HEIGHT +
    HEADER_GAP +
    ITEMS.length * ITEM_HEIGHT +
    (ITEMS.length - 1) * ITEM_GAP;

  return (
    <AbsoluteFill
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          position: "relative",
          width: 1100,
          height: fullStackHeight,
          transform: `translateY(${headerDrift}px)`,
        }}
      >
        {/* Header — anchored at the top */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            display: "flex",
            alignItems: "center",
            gap: 32,
            opacity: headerIn,
            transform: `translateY(${interpolate(headerIn, [0, 1], [40, 0])}px) scale(${interpolate(headerIn, [0, 1], [0.94, 1])})`,
          }}
        >
          <div
            style={{
              width: 132,
              height: 132,
              borderRadius: 28,
              background: ORANGE_SOLID_TINT,
              border: `2px solid ${COLORS.orange}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
            }}
          >
            <div style={{ transform: "scale(1.5)" }}>
              <Icon name="script" color={COLORS.orange} />
            </div>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <div
              style={{
                fontFamily: "'GT Walsheim', Inter, sans-serif",
                fontSize: 64,
                fontWeight: 600,
                color: COLORS.text,
                letterSpacing: "-0.02em",
                lineHeight: 1,
              }}
            >
              Every competitor script
            </div>
            <div
              style={{
                opacity: eyebrowIn,
                transform: `translateX(${interpolate(eyebrowIn, [0, 1], [-16, 0])}px)`,
                fontFamily: "monospace",
                fontSize: 30,
                letterSpacing: "0.22em",
                textTransform: "uppercase",
                color: COLORS.orange,
              }}
            >
              Analyze
            </div>
          </div>
        </div>

        {/* List — each item absolutely positioned at its fixed slot so
            the header NEVER shifts as new rows appear */}
        {ITEMS.map((it, i) => {
          const itemIn = springIn(frame, vfps, it.start, "ELASTIC");
          if (itemIn < 0.001) return null;
          const isActive = i === activeIdx;
          const accent = isActive ? COLORS.orange : COLORS.border;
          const iconColor = isActive ? COLORS.orange : COLORS.textMuted;

          const since = frame - it.start;
          const punch = interpolate(since, [0, 4, 12], [1, 1.03, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const slotTop =
            HEADER_HEIGHT + HEADER_GAP + i * (ITEM_HEIGHT + ITEM_GAP);

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                top: slotTop,
                left: 0,
                right: 0,
                height: ITEM_HEIGHT,
                opacity: itemIn,
                transform: `translateY(${interpolate(itemIn, [0, 1], [24, 0])}px) translateX(${interpolate(itemIn, [0, 1], [-30, 0])}px) scale(${interpolate(itemIn, [0, 1], [0.92, 1]) * punch})`,
                display: "flex",
                alignItems: "center",
                gap: 36,
                background: isActive ? ORANGE_SOLID_TINT : COLORS.card,
                border: `2px solid ${accent}`,
                borderRadius: 26,
                padding: "30px 44px",
                boxSizing: "border-box",
                boxShadow: isActive
                  ? `0 20px 60px ${COLORS.orange}33`
                  : "0 16px 48px rgba(0,0,0,0.45)",
              }}
            >
              <div
                style={{
                  width: 96,
                  height: 96,
                  borderRadius: 20,
                  background: isActive
                    ? "rgb(72, 35, 15)"
                    : "rgba(255,255,255,0.05)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  flexShrink: 0,
                }}
              >
                <Icon name={it.icon} color={iconColor} />
              </div>
              <div
                style={{
                  fontFamily: "'GT Walsheim', Inter, sans-serif",
                  fontSize: 56,
                  fontWeight: 600,
                  color: isActive ? COLORS.text : COLORS.textMuted,
                  letterSpacing: "-0.015em",
                }}
              >
                {it.label}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default MainComposition;
